const SAMLService = require('../services/samlService');
const Service = require('../models/Service');
const User = require('../models/User');
const config = require('../config/config');

class SAMLController {
    static metadata(req, res) {
        const metadata = SAMLService.generateMetadata();
        res.set('Content-Type', 'text/xml');
        res.send(metadata);
    }

    static async sso(req, res) {
        const { SAMLRequest, RelayState } = req.query;

        if (!req.session || !req.session.userId) {
            const loginUrl = `/login?SAMLRequest=${encodeURIComponent(SAMLRequest || '')}&RelayState=${encodeURIComponent(RelayState || '')}`;
            return res.redirect(loginUrl);
        }

        if (req.session.userType !== 0) {
            return res.status(403).render('error', {
                title: 'Access Denied',
                message: 'You do not have permission to use SAML services.',
                user: req.user
            });
        }

        try {
            const user = await User.findById(req.session.userId);
            if (!user) {
                return res.redirect('/login');
            }

            let acsUrl = null;
            let entityId = null;
            let requestId = null;
            let matchedService = null;

            if (SAMLRequest) {
                const validation = await SAMLService.validateSAMLRequest(SAMLRequest);
                if (!validation.valid) {
                    return res.status(400).render('error', {
                        title: 'Invalid SAML Request',
                        message: validation.message,
                        user: req.user
                    });
                }

                const parsed = validation.data;
                if (parsed) {
                    acsUrl = parsed.acsUrl;
                    entityId = parsed.entityId;
                    requestId = parsed.requestId;

                    const requestIdValidation = await SAMLService.validateRequestId(
                        requestId, 
                        parsed.issueInstant
                    );
                    if (!requestIdValidation.valid) {
                        return res.status(400).render('error', {
                            title: 'SAML Request Validation Failed',
                            message: requestIdValidation.message,
                            user: req.user
                        });
                    }

                    matchedService = await Service.findByAcsUrl(acsUrl);
                    if (!matchedService) {
                        return res.status(403).render('error', {
                            title: 'Service Not Authorized',
                            message: 'This service is not registered in the system or has been disabled',
                            user: req.user
                        });
                    }

                    if (matchedService.config.entity_id && 
                        matchedService.config.entity_id !== entityId) {
                        return res.status(403).render('error', {
                            title: 'Service Identity Mismatch',
                            message: 'Entity ID validation failed',
                            user: req.user
                        });
                    }
                }
            }

            if (!acsUrl && RelayState) {
                const service = await Service.findByServiceId(RelayState);
                if (service && service.protocol === 'saml' && service.enabled) {
                    acsUrl = service.config.acs_url;
                    entityId = service.config.entity_id;
                    matchedService = service;
                } else {
                    return res.status(400).render('error', {
                        title: 'Service Not Found',
                        message: 'The specified service was not found or has been disabled',
                        user: req.user
                    });
                }
            }

            if (!acsUrl) {
                return res.status(400).render('error', {
                    title: 'Parameter Error',
                    message: 'Missing required SAML parameters',
                    user: req.user
                });
            }

            const encodedResponse = await SAMLService.generateSAMLResponse(user, {
                acsUrl,
                entityId,
                requestId
            });

            res.render('saml_post', {
                title: 'Logging in...',
                acsUrl,
                samlResponse: encodedResponse,
                relayState: RelayState || ''
            });

        } catch (error) {
            console.error('[SAML] SSO processing failed:', error.message);
            console.error(error);
            return res.status(500).render('error', {
                title: 'Server Error',
                message: 'An error occurred while processing the SAML request. Please try again later',
                user: req.user
            });
        }
    }

    static async slo(req, res) {
        const { SAMLRequest, RelayState } = req.query;

        try {
            if (req.session) {
                req.session.destroy();
            }

            if (SAMLRequest) {
                const decoded = SAMLService.decodeSAMLRequest(SAMLRequest);

                const requestIdMatch = decoded?.match(/ID="([^"]+)"/);
                const destinationMatch = decoded?.match(/Destination="([^"]+)"/);

                const logoutResponseUrl = await SAMLService.generateSAMLLogoutResponse({
                    inResponseTo: requestIdMatch ? requestIdMatch[1] : undefined,
                    destination: destinationMatch ? destinationMatch[1] : undefined
                });

                if (typeof logoutResponseUrl === 'string') {
                    if (logoutResponseUrl.startsWith('http')) {
                        return res.redirect(logoutResponseUrl);
                    } else {
                        const encodedResponse = SAMLService.encodeSAMLResponse(logoutResponseUrl);
                        if (destinationMatch && destinationMatch[1]) {
                            const redirectUrl = `${destinationMatch[1]}?SAMLResponse=${encodeURIComponent(encodedResponse)}${RelayState ? `&RelayState=${encodeURIComponent(RelayState)}` : ''}`;
                            return res.redirect(redirectUrl);
                        }

const SAMLIdentityProvider = require('../utils/saml');
const config = require('../config/config');

class SAMLService {
    static getIdentityProvider() {
        if (!this.idp) {
            const certificate = config.getCertificate();
            const privateKey = config.getPrivateKey();
            const samlConfig = config.getSamlConfig();

            this.idp = new SAMLIdentityProvider({
                issuer: process.env.SAML_ISSUER || samlConfig.issuer,
                certificate: certificate,
                privateKey: privateKey
            });
        }
        return this.idp;
    }

    static async generateSAMLResponse(user, options = {}) {
        const idp = this.getIdentityProvider();

        const userInfo = {
            id: user.id,
            uid: String(user.id || ''),
            username: user.username || '',
            email: user.email || user.username || '',
            displayName: user.display_name || user.username || '',
            display_name: user.display_name || user.username || '',
            role: user.role || 'user',
            department: user.department || ''
        };

        const responseOptions = {
            requestId: options.requestId,
            acsUrl: options.acsUrl || options.acs_url,
            destination: options.acsUrl || options.acs_url,
            entityId: options.entityId || options.entity_id,
            audience: options.entityId || options.entity_id,
            nameIDFormat: options.nameIDFormat || 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified'
        };

        const responseXml = idp.createLoginResponse(userInfo, responseOptions);
        return SAMLIdentityProvider.encodeResponse(responseXml);
    }

    static async parseSAMLRequest(samlRequest, binding = 'redirect') {
        try {
            const idp = this.getIdentityProvider();
            const parsed = idp.parseAuthnRequest(samlRequest, binding);

            return {
                requestId: parsed.requestId,
                acsUrl: parsed.acsUrl,
                entityId: parsed.issuer,
                issueInstant: parsed.issueInstant,
                destination: parsed.destination,
                protocolBinding: parsed.protocolBinding,
                forceAuthn: parsed.forceAuthn,
                isPassive: parsed.isPassive,
                nameIDFormat: parsed.nameIDFormat,
                allowCreate: parsed.allowCreate
            };
        } catch (error) {
            console.error('[SAML Service] Failed to parse SAML request:', error.message);
            return null;
        }
    }

    static async validateSAMLRequest(samlRequest) {
        if (!samlRequest) {
            return { valid: false, message: 'Missing SAML request' };
        }

        try {
            const parsed = await this.parseSAMLRequest(samlRequest);
            if (!parsed) {
                return { valid: false, message: 'Invalid SAML request format' };
            }
            return { valid: true, data: parsed };
        } catch (error) {
            console.error('[SAML Service] SAML request validation failed:', error.message);
            return { valid: false, message: error.message };
        }
    }

    static async validateRequestId(requestId, issueInstant) {
        const idp = this.getIdentityProvider();
        return idp.validateRequestId(requestId, issueInstant);
    }

    static generateMetadata() {
        try {
            const idp = this.getIdentityProvider();
            const serverConfig = config.getServerConfig();
            const samlConfig = config.getSamlConfig();
            const baseUrl = process.env.BASE_URL || `http://${serverConfig.host}:${serverConfig.port}`;

            return idp.getMetadata({
                entityID: process.env.SAML_ISSUER || samlConfig.issuer,
                ssoLocation: `${baseUrl}/saml/sso`,
                sloLocation: `${baseUrl}/saml/slo`,
                nameIDFormats: ['urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified']
            });
        } catch (error) {
            console.error('[SAML Service] Failed to generate metadata:', error.message);
            console.error(error);
            throw error;
        }
    }

    static async generateSAMLLogoutResponse(options = {}) {
        try {
            const idp = this.getIdentityProvider();

            const logoutResponseOptions = {
                inResponseTo: options.inResponseTo,
                destination: options.destination || options.acsUrl
            };

            const responseXml = idp.createLogoutResponse(logoutResponseOptions);
            return responseXml;
        } catch (error) {
            console.error('[SAML Service] Failed to generate logout response:', error.message);
            console.error(error);
            throw error;
        }
    }

    static encodeSAMLResponse(samlResponse) {
        return SAMLIdentityProvider.encodeResponse(samlResponse);
    }

    static decodeSAMLRequest(samlRequest) {
        try {
            return SAMLIdentityProvider.decodeRequest(samlRequest, 'redirect');
        } catch (error) {
            console.error('[SAML Service] Failed to decode SAML request:', error.message);
            return null;
        }
    }
}

module.exports = SAMLService;

